let hostile_fleets = if matches!(fog, FogState::Visible) {
    game_state
        .fleets
        .values()
        .filter(|fleet| {
            game_state
                .stars
                .get(&fleet.location)
                .is_some_and(|star| star.sector == sector.id)
                && fleet.owner != game_state.player_empire
                && game_state
                    .relationship_status(game_state.player_empire, fleet.owner)
                    .is_hostile_or_war()
        })
        .count()
} else {
    0
};

let hostile_here = if matches!(fog, FogState::Visible) {
    game_state
        .fleets
        .values()
        .filter(|fleet| {
            fleet.location == star.id
                && fleet.owner != game_state.player_empire
                && game_state
                    .relationship_status(game_state.player_empire, fleet.owner)
                    .is_hostile_or_war()
        })
        .count()
} else {
    0
};

